// Writes the generated theme files from the palette. Runs on `bun install`, before typecheck and
// tests, and from each app's build. The outputs are gitignored: the palette is the only source.
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { DARK, LIGHT } from "../src/tokens/palette";
import { shadowThemeCss } from "../src/tokens/shadow-css.util";
import { themeCss } from "../src/tokens/theme-css.util";

const SRC = join(import.meta.dir, "..", "src");

const shadowModule = (css: string): string =>
  "// Generated by packages/ui/scripts/generate.ts from src/tokens/palette.ts. Don't edit.\n" +
  `export const SHADOW_THEME_CSS = ${JSON.stringify(css)};\n`;

/** Writes theme.generated.css and shadow-theme.generated.ts into `outdir` (default: src/). */
export const generate = async (outdir = SRC): Promise<void> => {
  await mkdir(outdir, { recursive: true });
  await Promise.all([
    Bun.write(join(outdir, "theme.generated.css"), themeCss(LIGHT, DARK)),
    Bun.write(join(outdir, "shadow-theme.generated.ts"), shadowModule(shadowThemeCss(LIGHT, DARK))),
  ]);
};

if (import.meta.main) await generate();
